WITH scored AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, SUM(discount_pct) OVER (PARTITION BY channel, promo_code ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount_pct, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY channel, promo_code), 4) AS discount_pct_share, LAG(discount_pct, 2) OVER (PARTITION BY channel ORDER BY starts_on, id) AS prev_discount_pct FROM promotions) SELECT id, promo_code, starts_on, ends_on, discount_pct, cumulative_discount_pct, discount_pct_share, prev_discount_pct, CASE WHEN promo_code RLIKE '^(SPRING10|BUNDLE)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS promo_code_zone FROM scored;
